'use strict';
window.addEventListener('click',event=>{const button=event.target.closest('[data-action="cancel-order"]');if(!window.KstoreCloud?.enabled||!button)return;event.preventDefault();event.stopImmediatePropagation();modal('Cancel order?','<p>This cancels your order before shipment and restores the reserved stock. No pay-on-delivery payment has been collected.</p><button class="primary" data-action="confirm-cancel" data-value="'+esc(button.dataset.value)+'">Confirm cancellation</button>');},true);
// The Firebase client module calls this bridge; null configuration preserves the existing demo.
window.KstoreCloud={enabled:!!window.KSTORE_FIREBASE,ready:false,catalogReady:false,auth:null,quote:null,publicListings:new Map(),ownedListings:new Map(),stores:new Map(),scheduleSave(){},applyCatalog(){}};
window.KstoreFirebaseUI={authMode:'signin',error:'',message:'',original:{home,login,summary,reviewStep,sellerOnboarding,sellerStore},
  authPage(){const ui=this,register=ui.authMode==='register',reset=ui.authMode==='reset';return '<section class="panel" style="max-width:460px;margin:40px auto"><div class="logo"><img src="assets/kstore-logo.png" alt="Kstore"></div><h1 class="page-title">'+(register?'Create your Kstore account':reset?'Reset your password':'Welcome back.')+'</h1><p class="muted small">Sign in securely to save your finds and manage your account.</p><form id="firebase-auth-form">'+(register?'<label class="field">Your name<input name="name" required maxlength="70" autocomplete="name"></label>':'')+'<label class="field">Email<input name="email" type="email" required autocomplete="email"></label>'+(!reset?'<label class="field">Password<input name="password" type="password" required minlength="8" autocomplete="'+(register?'new-password':'current-password')+'"></label>':'')+'<p class="error" role="alert">'+esc(ui.error)+'</p><p class="success" role="status">'+esc(ui.message)+'</p><button class="primary full">'+(register?'Create account':reset?'Send reset email':'Sign in')+'</button></form><div style="display:flex;gap:15px;margin-top:20px"><button class="text small" data-firebase-mode="'+(register||reset?'signin':'register')+'">'+(register||reset?'Sign in instead':'Create an account')+'</button>'+(!reset?'<button class="text small" data-firebase-mode="reset">Forgot password?</button>':'')+'</div></section>'},
  showError(error){this.error=error?.message||'The operation failed. Please retry.';toast(this.error)},
  catalogProduct(p){return {...p,stock:p.variants.reduce((n,v)=>n+Number(v.stock),0),image:p.images[0],gallery:p.images.map((src,i)=>({src,full:src,thumb:src,label:i===0?'Main image':'Image '+(i+1)})),variants:p.variants.map(v=>v.name),variantStock:Object.fromEntries(p.variants.map(v=>[v.name,v.stock])),unavailable:p.variants.filter(v=>v.stock===0).map(v=>v.name),listingStatus:p.status,rating:0,reviews:0,official:false,specs:{Description:p.description,Condition:p.condition,SKU:p.sku}}},
  loading(){if(KstoreCloud.fatal)return '<div class="panel empty"><h2>Account connection unavailable</h2><p class="error">'+esc(KstoreCloud.fatal)+'</p><button class="primary" data-firebase-action="retry">Retry</button> <button class="secondary" data-firebase-action="signout">Sign out</button></div>';return '<div class="panel empty"><h2>Connecting your account…</h2><p class="muted">Loading secure account and catalog data.</p></div>'}
};
const cloudOriginalHome=home;home=function(){if(!KstoreCloud.enabled)return cloudOriginalHome();return '<div class="home-top" style="display:block"><section class="hero"><div class="hero-copy"><span class="eyebrow">YOUR EVERYDAY, UPGRADED</span><h1>Good finds.<br><em>More possibilities.</em></h1><p>Discover products from Kstore sellers.</p><a class="primary" href="#/catalog">Explore the collection →</a></div></section></div><section class="section"><div class="section-head"><h2>Discover the marketplace</h2><a href="#/sell">Become a seller →</a></div>'+(products.filter(p=>p.listingStatus==='active').length?'<div class="product-grid">'+products.filter(p=>p.listingStatus==='active').slice(0,10).map(card).join('')+'</div>':'<div class="panel empty"><h2>New finds are on their way.</h2><p class="muted">Approved seller listings will appear here.</p><a class="primary" href="#/sell">Start selling</a></div>')+'</section>'};
const cloudOriginalLogin=login;login=function(){return KstoreCloud.enabled?KstoreFirebaseUI.authPage():cloudOriginalLogin()};
const cloudOriginalSync=syncSellerProducts;syncSellerProducts=function(){if(KstoreCloud.enabled)return KstoreCloud.applyCatalog();return cloudOriginalSync()};
const cloudOriginalOnboarding=sellerOnboarding;sellerOnboarding=function(){if(KstoreCloud.enabled&&!state.user)return login();if(KstoreCloud.enabled&&!KstoreCloud.auth?.emailVerified)return '<section class="panel empty"><h1>Verify your email to start selling.</h1><p class="muted">Check your inbox, then refresh verification status.</p><button class="primary" data-firebase-action="verify">Send verification email</button> <button class="secondary" data-firebase-action="refresh-auth">I have verified my email</button></section>';return cloudOriginalOnboarding()};
const cloudOriginalSummary=summary;summary=function(checkout=false){if(!KstoreCloud.enabled||!checkout)return cloudOriginalSummary(checkout);const q=KstoreCloud.quote;return '<div class="panel"><h3>Order summary</h3>'+(q?'<div class="summary-row"><span>Merchandise</span><b>'+money(q.subtotal)+'</b></div><div class="summary-row"><span>Delivery</span><b>'+money(q.shipping)+'</b></div><div class="summary-row"><span>Discount</span><b>−'+money(q.discount)+'</b></div><div class="summary-row total"><span>Total</span><b>'+money(q.total)+'</b></div>':'<p class="muted small">Choose delivery, then request your current server quote.</p>')+'</div>'};
const cloudOriginalReview=reviewStep;reviewStep=function(){if(!KstoreCloud.enabled)return cloudOriginalReview();return '<h2>Review your order</h2>'+state.cart.map(l=>'<div class="summary-row"><span>'+esc(getP(l.id)?.name||'Unavailable product')+' × '+l.qty+'</span><b>'+money((getP(l.id)?.price||0)*l.qty)+'</b></div>').join('')+'<p class="small">Payment: Pay on delivery. Online payments are not connected.</p><label class="small"><input id="accept-order" type="checkbox"> I confirm the delivery details and server-quoted total.</label><div class="spacer"></div><button class="primary full" data-action="place-order" '+(!KstoreCloud.quote?'disabled':'')+'>Place order'+(KstoreCloud.quote?' · '+money(KstoreCloud.quote.total):'')+'</button><p id="order-error" class="error" role="alert"></p>'};
const cloudOriginalStore=sellerStore;sellerStore=function(){if(!KstoreCloud.enabled)return cloudOriginalStore();const id=route().path.split('/')[3],s=KstoreCloud.stores.get(id);if(!s)return '<section class="panel empty"><h2>Store information unavailable</h2><p class="muted">This store may still be awaiting approval.</p></section>';const items=products.filter(p=>p.sellerId===id&&p.listingStatus==='active');return '<section class="panel section"><h1>'+esc(s.shopName)+'</h1><p>'+esc(s.description||'')+'</p><span class="status">Approved seller</span></section><div class="product-grid catalog-grid">'+items.map(card).join('')+'</div>'};
const cloudOriginalRender=render;render=function(){if(KstoreCloud.enabled&&(!KstoreCloud.ready||!KstoreCloud.catalogReady)){$('#app').innerHTML=header()+'<main class="wrap">'+KstoreFirebaseUI.loading()+'</main>';return}cloudOriginalRender();if(KstoreCloud.enabled){const copy={ 'Demo setup only. No identity verification or payout account is opened. Never enter bank account numbers or real identity documents here.':'Seller applications are saved securely. Publishing requires operator approval. Payouts are not connected; do not enter bank account numbers or identity documents here.', 'Use sample details for this browser-only demo.':'Your profile is saved to your account.', 'Your progress is saved in this browser after each step.':'Your application progress is saved to your account after each step.', 'Create demo store →':'Submit seller application →', 'Publish in demo catalog':'Publish after approval', 'Upload your first product':'Upload your first product', 'This interactive demo saves listings in this browser. Published listings appear in this browser’s catalog. A shared marketplace requires authenticated server storage.':'Your seller profile and listings are saved to your account. Approved active listings are shared across shoppers.', 'I understand this creates a browser-local demo store, not a verified seller account.':'I understand that publishing requires seller review and that payout setup is not connected.', 'Sample review · Demo content':'Illustrative review — not a customer purchase' };const walker=document.createTreeWalker($('main'),NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode;if(copy[node.textContent.trim()])node.textContent=copy[node.textContent.trim()]}$('.demo-strip').textContent='Firebase connected · Online payments are not connected';$$('.seller-demo-note').forEach(e=>e.textContent='Seller center · Publication requires approval.');$$('.status').forEach(e=>{if(/Demo store active/.test(e.textContent))e.textContent=state.seller?.verificationStatus==='approved'?'Approved seller':'Approval pending';});$$('.notice').forEach(e=>{if(e.textContent.includes('Demo checkout'))e.textContent='Your order uses server-validated prices and inventory. Online payments are not connected.'});if(state.user&&!KstoreCloud.auth?.emailVerified){const m=document.createElement('div');m.className='notice';m.innerHTML='Verify your email before selling or placing orders. <button class="text" data-firebase-action="verify">Send verification email</button> <button class="text" data-firebase-action="refresh-auth">Refresh status</button>';$('main').prepend(m)}}};

const cloudOriginalAccountContent=accountContent;accountContent=function(tab){if(KstoreCloud.enabled&&tab==='vouchers')return '<div class="panel"><h2>Your vouchers</h2><p class="muted">Only promotions configured by the operator can be applied at checkout.</p></div>';return cloudOriginalAccountContent(tab)};

// Connected mode must not advertise sample fees, vouchers or payment providers.
const connectedAuthPage=KstoreFirebaseUI.authPage;
KstoreFirebaseUI.authPage=function(){return connectedAuthPage.call(this).replace('name="email" type="email"','name="email" value="'+esc(this.authEmail||'')+'" type="email"');};
window.addEventListener('submit',event=>{if(KstoreCloud.enabled&&event.target.id==='firebase-auth-form')KstoreFirebaseUI.authEmail=String(new FormData(event.target).get('email')||'').trim();},true);
const connectedAccountContent=accountContent;
accountContent=function(tab){
  if(!KstoreCloud.enabled)return connectedAccountContent(tab);
  if(tab==='orders'&&!state.orders.length)return empty('No orders yet','Your orders will appear here.');
  if(tab==='pickups')return '<button class="primary" data-action="pickup">＋ Add pickup station</button>'+state.pickups.map(s=>'<div class="panel" style="margin-top:15px"><h3>'+esc(s.name)+'</h3><p>'+esc(s.city)+', '+esc(s.region)+'</p><button data-action="delete-pickup" data-value="'+esc(s.id)+'" class="text">Remove</button></div>').join('');
  if(tab==='reviews'){
    const ids=[...new Set(state.orders.filter(o=>o.buyerId===KstoreCloud.auth?.uid&&o.status==='Delivered').flatMap(o=>o.lines.map(l=>l.id)))].filter(id=>!state.reviews.some(r=>r.id===id&&r.authorUid===KstoreCloud.auth?.uid));
    return ids.length?ids.map(id=>'<div class="panel"><h3>'+esc(getP(id)?.name||'Purchased product')+'</h3><button class="secondary" data-action="review" data-id="'+esc(id)+'">Write a review</button></div>').join(''):empty('You’re all caught up','Delivered purchases eligible for a review will appear here.');
  }
  return connectedAccountContent(tab).replace('<h3>A welcome treat</h3><p>Take 10% off with <b>WELCOME10</b>.</p>','<h3>Discover the marketplace</h3><p>Explore products from approved sellers.</p>');
};
const connectedFooter=footer;
footer=function(){if(!KstoreCloud.enabled)return connectedFooter();return connectedFooter().replace(/<section class="newsletter">[\s\S]*?<\/section>/,'').replace('◇ &nbsp; Secure checkout<br>↶ &nbsp; Easy returns<br>▱ &nbsp; Trusted payment options','◇ &nbsp; Secure account access<br>↶ &nbsp; Returns from eligible delivered orders').replace('VISA &nbsp; Mastercard &nbsp; MTN MoMo','Online payments are not available.');};
const connectedDeliveryStep=deliveryStep;
deliveryStep=function(){const html=connectedDeliveryStep();return KstoreCloud.enabled?html.replace('Door delivery · '+money(35),'Door delivery · Fee confirmed in your quote').replace('Pickup station · '+money(14),'Pickup station · Fee confirmed in your quote').replaceAll(' · Mon–Fri 8:30–17:30',''):html;};
const connectedPickupModal=pickupModal;
pickupModal=function(){if(!KstoreCloud.enabled)return connectedPickupModal();modal('Find a pickup station',stations.length?'<p class="muted">Choose an available station. Delivery fees are confirmed in your quote.</p>'+stations.map(s=>'<div class="order"><h3>'+esc(s.name)+'</h3><p>'+esc(s.city)+' · '+esc(s.region)+'</p><button class="primary" data-action="save-pickup" data-value="'+esc(s.id)+'">Select station</button></div>').join(''):'<p>No pickup stations are available yet.</p>');};
const connectedInfoPage=infoPage;
infoPage=function(id){if(!KstoreCloud.enabled)return connectedInfoPage(id);const pages={
  about:['Your everyday, upgraded.','Kstore is a Ghana-focused marketplace. Products appear after seller approval and publication.'],
  shipping:['Delivery, your way.','Available destinations, pickup stations and delivery fees are checked when you request a checkout quote. Ordering must be enabled by the store operator.'],
  returns:['Returns and refunds','You can request a return from an eligible delivered order. Collection and refund processing require confirmation; submitting a request does not complete a refund.'],
  payments:['Ways to pay.','Only pay on delivery is supported when ordering is enabled. Card and mobile money payments are not connected.'],
  privacy:['Your privacy matters.','Your account profile, addresses and preferences are saved to your signed-in account. Product photos and approved listings are public. Signing out removes account data from the current page; it does not delete your stored account.'],
  terms:['A few things to know.','The marketplace is being prepared for trading. Seller publication requires approval. Orders require an enabled checkout and a current quote. Delivery, online payments, refunds and payouts require operational confirmation or additional services.'],
  sell:['Bring your store to Kstore.','Create an account and verify your email to submit a seller application. Approval is required to publish products. Payouts are not connected.'],
  contact:['Help with your account','Support messaging is not available yet. You can view order information in your account.']
};const [title,copy]=pages[id]||pages.about;return '<section class="panel legal"><h1 class="page-title">'+title+'</h1><p>'+copy+'</p></section>';};
const connectedRender=render;
render=function(){connectedRender();if(KstoreCloud.enabled){const estimate=$('#estimate');if(estimate)estimate.textContent='Delivery fees are confirmed in your checkout quote.';const strip=$('.demo-strip');if(strip)strip.textContent='Account connected · Online payments are not available';}};

const connectedSellerLanding=sellerLanding;
sellerLanding=function(){const html=connectedSellerLanding();if(!KstoreCloud.enabled)return html;return html.replaceAll('demo payout preference','payout preference (payouts are not connected)').replace('Business verification and real payout setup require a live seller service.','Applications require approval before publication. Payout accounts are not connected.').replace('This demo uses a clearly labeled sample 5% commission to illustrate finance calculations. It is not a production pricing agreement.','Fees and settlement terms have not been configured. No payable balance is created.').replace('No. Onboarding and seller operations are simulated. Do not enter real identity documents, bank account numbers or confidential business information.','Your application is saved to your account and requires review. Do not enter identity documents or bank account numbers; payouts are not connected.');};
const connectedSellerFinance=sellerFinance;
sellerFinance=function(){if(!KstoreCloud.enabled)return connectedSellerFinance();return '<div class="panel"><h2>Order merchandise total</h2><strong>'+money(sellerRevenue())+'</strong><p class="muted">This is the merchandise value of non-cancelled orders, not collected payments or a payable balance.</p><p>Commissions, settlements and payouts have not been configured.</p></div>';};
const connectedSellerOrderRow=sellerOrderRow;
sellerOrderRow=function(order){const html=connectedSellerOrderRow(order);return KstoreCloud.enabled?html.replace('Demo delivery:','Delivery:').replace(/<button[^>]*data-seller="order-status"[^>]*data-value="(?:Delivered|Refunded)"[^>]*>[\s\S]*?<\/button>/g,''):html;};
const connectedSellerListingEditor=sellerListingEditor;
sellerListingEditor=function(id){connectedSellerListingEditor(id);if(!KstoreCloud.enabled)return;const status=$('#seller-product-form [name="status"]'),listing=state.seller.listings.find(l=>l.id===id);status.querySelector('[value="active"]').textContent='Publish after approval';for(const value of ['paused','archived']){const option=document.createElement('option');option.value=value;option.textContent=value[0].toUpperCase()+value.slice(1);status.append(option);}status.value=listing?.status||'draft';const note=$$('#seller-product-form p').find(p=>p.textContent.includes('Uploads are resized'));if(note)note.textContent='Photos are resized, then uploaded when you save the product.';};

if(!KstoreCloud.enabled)render();else{$('#app').innerHTML='<main class="wrap">'+KstoreFirebaseUI.loading()+'</main>'}

window.dispatchEvent(new Event("kstore-ui-ready"));
